mapper.select:
select 'store' as sourceType, id as sourceId, name as name,
       location_lat as latitude, location_lng as longitude, address as address,
       logo as cover, business_status as businessStatus
from mms_merchant
where status = 1 and account_status = 1 and del_flag = 0
  and location_lat is not null and location_lng is not null
  and location_lat between #{minLat} and #{maxLat}
  and location_lng between #{minLng} and #{maxLng}
  and id > #{afterId}
order by id asc
limit #{limit}
